import re

def tag_sentence(sentence):
    # Define regular expressions for claims and premises
    claim_pattern = r"(\w+ \w+)|(\w+)|do (\w+ to know)"
    premise_pattern = r"(about presidential candidates)|(especially about presidents)|(when they're facing some kind of challenge)"

    # Find all matches for claims and premises
    claims = re.findall(claim_pattern, sentence)
    premises = re.findall(premise_pattern, sentence)

    # Tag the sentence with claims and premises
    for i, claim in enumerate(claims):
        if i == 0:
            sentence = sentence.replace(claim[0], f"<claim>{claim[0]}</claim>", 1)
        elif i == 1:
            sentence = sentence.replace(claim[0], f"<claim>{claim[0]}</claim>", 1)
        else:
            sentence = sentence.replace(claim[0], f"<claim>{claim[0]}</claim>", 1)

    for i, premise in enumerate(premises):
        if i == 0:
            sentence = sentence.replace(premise[0], f"<premise>{premise[0]}</premise>", 1)
        elif i == 1:
            sentence = sentence.replace(premise[0], f"<premise>{premise[0]}</premise>", 1)
        else:
            sentence = sentence.replace(premise[0], f"<premise>{premise[0]}</premise>", 1)

    return sentence

