def task(sentence):
    # Define the possible span types and their corresponding keywords
    span_types = {
        '<claim>': ['expresses', 'opinion', 'proposed'],
        '<premise>': ['justification','support']
    }

    # Initialize an empty list to store the tagged spans
    tagged_spans = []

    # Split the sentence into individual words
    words = sentence.split()

    # Iterate over each word in the sentence
    for i in range(len(words)):
        # Check if the current word is the first word in the sentence
        if i == 0:
            continue

        # Get the previous word
        prev_word = words[i-1]

        # Check if the current word matches a claim type keyword
        for key, value in span_types.items():
            if any(word in value for word in value) and (prev_word.lower() == 'expresses' or prev_word.lower() == 'opinion'):
                # If it does, append the tagged span to the list
                tagged_spans.append((i, f'{key}{words[i]}{key}'))

    # Join the original sentence with the tagged spans
    output_sentence = ''
    for i, word in enumerate(words):
        if (i, f'<claim>{word}</claim>') in tagged_spans:
            output_sentence += f'<claim>{word}</claim>'
        elif (i, f'<premise>{word}</premise>') in tagged_spans:
            output_sentence += f'<premise>{word}</premise>'
        else:
            output_sentence += word +''

    return output_sentence.strip()
