import re

def tag_sentence(sentence):
    claims = []
    premises = []

    # Find all phrases that could be claims
    claim_phrases = ["pledged to", "turned very"]
    for phrase in claim_phrases:
        matches = re.findall(r"\b" + phrase + r"\b\s+[^\s]+", sentence)
        for match in matches:
            start = sentence.find(match)
            end = start + len(match)
            while sentence[end]!= " ":
                end += 1
            claims.append((start, end))

    # Find all phrases that could be premises
    premise_phrases = ["in this campaign"]
    for phrase in premise_phrases:
        matches = re.findall(r"\b" + phrase + r"\b\s+[^\s]+", sentence)
        for match in matches:
            start = sentence.find(match)
            end = start + len(match)
            while sentence[end]!= " ":
                end += 1
            premises.append((start, end))

    # Tag the sentence
    tagged_sentence = list(sentence)
    for i, char in enumerate(tagged_sentence):
        if (i, i+1) in claims:
            tagged_sentence[i] = "<claim>"
            tagged_sentence[i+1] = "</claim>"
        elif (i, i+1) in premises:
            tagged_sentence[i] = "<premise>"
            tagged_sentence[i+1] = "</premise>"

    return "".join(tagged_sentence)

sentence = "All right. We're going to move to another question and the topic is leadership in this campaign. Both of you pledged to take the high road in this campaign yet it has turned very nasty."
print(tag_sentence(sentence))
