import re

def process(sentence):
    # Claim
    claims = re.findall(r'\b\w+\b', sentence)
    for i in range(len(claims)):
        if claims[i] == "plan" and (i > 0 and claims[i - 1]!= "what") or (i < len(claims) - 1 and claims[i + 1]!= "is"):
            continue
        sentence = sentence.replace(claims[i], "<claim>" + claims[i] + "</claim>", 1)

    # Premise
    premises = re.findall(r'\b\w+\b', sentence)
    for i in range(len(premises)):
        if premises[i] == "fine":
            if (i > 0 and premises[i - 1]!= "pay") or (i < len(premises) - 1 and premises[i + 1]!= "because"):
                continue
            sentence = sentence.replace(premises[i], "<premise>" + premises[i] + "</premise>", 1)
        elif premises[i] == "zero":
            if (i > 0 and premises[i - 1]!= "fine") or (i < len(premises) - 1 and premises[i + 1]!= "--"):
                continue
            sentence = sentence.replace(premises[i], "<premise>" + premises[i] + "</premise>", 1)
    return sentence

