def tag_sentence(sentence):
    # Define the possible tags and their corresponding patterns
    tags = {
        '<claim>': ['expresses', 'opinion','stance', 'proposed'],
        '<premise>': ['justification','support']
    }

    # Split the sentence into words
    words = sentence.split()

    # Initialize an empty list to store the tagged words
    tagged_words = []

    # Iterate over each word in the sentence
    for i, word in enumerate(words):
        # Check if the word is a claim (i.e., it's at the beginning of the sentence)
        if i == 0:
            # If the word matches a claim pattern, tag it as a claim
            for tag, patterns in tags.items():
                for pattern in patterns:
                    if pattern in word.lower():
                        tagged_words.append(f'<{tag}>{word}</{tag}>')
                        break
            else:
                # If the word doesn't match any claim pattern, leave it untagged
                tagged_words.append(word)
        else:
            # For non-first words, check if they're premises (i.e., they contain "because" or "since")
            if 'because' in word.lower() or'since' in word.lower():
                # If the word contains "because" or "since", tag it as a premise
                tagged_words.append(f'<premise>{word}</premise>')
            elif any(pattern in word.lower() for pattern in tags['<claim>']):
                # If the word contains a claim pattern, tag it as a claim
                for tag, patterns in tags.items():
                    for pattern in patterns:
                        if pattern in word.lower():
                            tagged_words.append(f'<{tag}>{word}</{tag}>')
                            break
                else:
                    # If the word doesn't match any claim or premise pattern, leave it untagged
                    tagged_words.append(word)
            else:
                # If the word doesn't contain any claim or premise patterns, leave it untagged
                tagged_words.append(word)

    # Join the tagged words back into a sentence
    tagged_sentence =''.join(tagged_words)

    return tagged_sentence

